use std::path::Path;

#[derive(Debug, PartialEq, Eq)]
pub enum Verdict { Pass, Fail, Incomplete }

pub trait Evaluator {
    /// Pass requires complete evidence; timeouts remain Incomplete.
    fn evaluate(&self, timed_out: bool) -> Verdict;
}

pub fn accept_delivery(evaluator: &dyn Evaluator, timed_out: bool) -> bool {
    evaluator.evaluate(timed_out) == Verdict::Pass
}

pub fn configured_limit(path: &Path) -> Result<u32, std::io::Error> {
    let text = std::fs::read_to_string(path)?;
    Ok(text.trim().parse().unwrap_or(100))
}

// Enrollment policy: eligibility age is positive. The registrar owns changes.
pub fn valid_age(age: i32) -> bool { age > 0 }
// Warehouse policy: requested quantity is positive. Inventory owns changes.
pub fn valid_quantity(quantity: i32) -> bool { quantity > 0 }

pub enum Mode { Quick, Full }
pub fn label(mode: Mode) -> &'static str {
    match mode { Mode::Quick => "quick", Mode::Full => "full" }
}

