use crate::domain::{Evaluator, Verdict};

pub struct Strict;
impl Evaluator for Strict {
    fn evaluate(&self, timed_out: bool) -> Verdict {
        if timed_out { Verdict::Incomplete } else { Verdict::Pass }
    }
}

pub struct Fast;
impl Evaluator for Fast {
    fn evaluate(&self, _timed_out: bool) -> Verdict { Verdict::Pass }
}

